import { readFileSync } from "node:fs";
import type { BrewingIngredientRole } from "../../beverages/brewing-types.ts";
import {
  FERMENTABLE_FAMILIES,
  INGREDIENT_FUNCTIONS,
  type IngredientFact,
  type IngredientResolution,
} from "./catalog-types.ts";

/** One maker-sourced catalog entry as stored in `sourced/<role>.json`. Every word carries the
 * maker's own phrase, and the source records where and when that text was read, so an entry can
 * be re-verified against the page. These entries are generated by
 * `scripts/flavor-sources/`; never edit words by hand. */
export interface SourcedEntry {
  readonly id: string;
  readonly manufacturer: string | null;
  readonly manufacturerAliases: readonly string[];
  readonly codes: readonly string[];
  readonly aliases: readonly string[];
  readonly descriptors: readonly { readonly word: string; readonly evidence: string }[];
  readonly source: {
    readonly url: string;
    /** `maker`: the maker's own page or data sheet. `maker-copy`: the maker's text as
     * reproduced elsewhere (`via`), used only when the maker's own copy is unavailable. */
    readonly kind: "maker" | "maker-copy";
    readonly via: string | null;
    readonly retrieved: string;
    readonly sha256: string;
  };
  readonly family: IngredientFact["family"];
  readonly souring: boolean | null;
  readonly functions: IngredientFact["functions"];
  readonly bodyClass: IngredientResolution["bodyClass"];
  readonly roastClass: IngredientResolution["roastClass"];
  readonly noticeableGPerL: number | null;
  readonly limitations: readonly string[];
}

const ROLES = ["fermentables", "hops", "yeasts", "miscs"] as const;
const BODY_CLASSES = ["oats", "flaked_wheat", "chit", "rye", "wheat", "carapils"] as const;
const ROAST_CLASSES = ["black", "chocolate", "dehusked", "none", "unknown"] as const;
const WORD = /^[a-z]+(?: [a-z]+){0,2}$/;

function fail(role: string, id: unknown, problem: string): never {
  throw new Error(`Sourced ${role} entry ${String(id)}: ${problem}.`);
}
const text = (value: unknown, max: number) =>
  typeof value === "string" && value.trim() !== "" && value.length <= max;
const texts = (value: unknown, max: number) =>
  Array.isArray(value) && value.every((item) => text(item, max));
const oneOf = <T extends string>(list: readonly T[], value: unknown): value is T =>
  typeof value === "string" && (list as readonly string[]).includes(value);

/** Validates one role's entries and converts them to catalog facts; any malformed entry throws,
 * so a bad dataset fails the test suite and startup rather than resolving silently. */
export function sourcedFacts(role: BrewingIngredientRole, value: unknown): IngredientFact[] {
  if (!Array.isArray(value)) fail(role, "file", "expected an array");
  return value.map((raw: unknown) => {
    const entry = (typeof raw === "object" && raw !== null ? raw : {}) as Record<string, unknown>;
    const id = entry["id"];
    if (typeof id !== "string" || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(id))
      fail(role, id, "id must be lowercase words joined by hyphens");
    const source = (entry["source"] ?? {}) as Record<string, unknown>;
    const manufacturer = entry["manufacturer"];
    if (manufacturer !== null && !text(manufacturer, 120))
      fail(role, id, "manufacturer must be a name or null");
    if (role !== "hops" && manufacturer === null)
      fail(role, id, "only hop varieties may omit the manufacturer");
    if (!texts(entry["manufacturerAliases"], 120) || !texts(entry["codes"], 64))
      fail(role, id, "manufacturer aliases and codes must be lists of names");
    if (!texts(entry["aliases"], 160) || (entry["aliases"] as unknown[]).length === 0)
      fail(role, id, "at least one exact name alias is required");
    const descriptors = entry["descriptors"];
    if (
      !Array.isArray(descriptors) ||
      descriptors.length > 8 ||
      !descriptors.every(
        (item: unknown) =>
          typeof item === "object" &&
          item !== null &&
          typeof (item as Record<string, unknown>)["word"] === "string" &&
          WORD.test((item as Record<string, string>)["word"]!) &&
          text((item as Record<string, unknown>)["evidence"], 80),
      ) ||
      new Set(descriptors.map((item: { word: string }) => item.word)).size !== descriptors.length
    )
      fail(role, id, "descriptors must be up to 8 distinct lowercase words, each with evidence");
    if (
      typeof source["url"] !== "string" ||
      !source["url"].startsWith("https://") ||
      !oneOf(["maker", "maker-copy"] as const, source["kind"]) ||
      (source["kind"] === "maker-copy") !== text(source["via"], 120) ||
      (source["kind"] === "maker" && source["via"] !== null) ||
      typeof source["retrieved"] !== "string" ||
      !/^\d{4}-\d{2}-\d{2}$/.test(source["retrieved"]) ||
      typeof source["sha256"] !== "string" ||
      !/^[0-9a-f]{64}$/.test(source["sha256"])
    )
      fail(role, id, "source needs an https URL, kind, via (copies only), date and sha256");
    const family = entry["family"];
    if (family !== null && !oneOf(FERMENTABLE_FAMILIES, family))
      fail(role, id, "unknown fermentable family");
    const souring = entry["souring"];
    if (souring !== null && typeof souring !== "boolean")
      fail(role, id, "souring must be boolean or null");
    const functions = entry["functions"];
    if (!Array.isArray(functions) || !functions.every((fn) => oneOf(INGREDIENT_FUNCTIONS, fn)))
      fail(role, id, "unknown ingredient function");
    const bodyClass = entry["bodyClass"];
    if (bodyClass !== null && !oneOf(BODY_CLASSES, bodyClass)) fail(role, id, "unknown body class");
    const roastClass = entry["roastClass"];
    if (!oneOf(ROAST_CLASSES, roastClass)) fail(role, id, "unknown roast class");
    const noticeable = entry["noticeableGPerL"];
    if (noticeable !== null && !(typeof noticeable === "number" && noticeable > 0))
      fail(role, id, "noticeableGPerL must be positive or null");
    if (!Array.isArray(entry["limitations"]) || !texts(entry["limitations"], 400))
      fail(role, id, "limitations must be a list of sentences");
    const via = source["kind"] === "maker-copy" ? String(source["via"]) : null;
    return Object.freeze({
      id,
      role,
      manufacturer: manufacturer as string | null,
      manufacturerAliases: Object.freeze([...(entry["manufacturerAliases"] as string[])]),
      codes: Object.freeze([...(entry["codes"] as string[])]),
      aliases: Object.freeze([...(entry["aliases"] as string[])]),
      family,
      descriptors: Object.freeze(descriptors.map((item: { word: string }) => item.word)),
      sourceUrls: Object.freeze([source["url"]]),
      reviewedAt: source["retrieved"],
      scope: "Maker-sourced categorical identity; not finished-beer intensity.",
      limitations: Object.freeze([
        ...(via ? [`Maker text as reproduced by ${via}.`] : []),
        ...(entry["limitations"] as string[]),
      ]),
      souring,
      functions: Object.freeze([...functions]),
      bodyClass,
      roastClass,
      noticeableGPerL: noticeable,
    } satisfies IngredientFact);
  });
}

/** Every role's maker-sourced facts, read once at startup from the bundled datasets. */
export const SOURCED_FACTS: readonly IngredientFact[] = Object.freeze(
  ROLES.flatMap((role) =>
    sourcedFacts(
      role,
      JSON.parse(readFileSync(new URL(`./sourced/${role}.json`, import.meta.url), "utf8")),
    ),
  ),
);
